def gen(rng):
    def val(s):
        t = 0
        for term in s.split('+'):
            p = 1
            for f in term.split('*'):
                p *= int(f)
            t += p
        return t
    def num(hi):
        return str(rng.randint(0, hi))
    def small(n, hi, pm=0.5):
        toks = [num(hi)]
        for _ in range(n - 1):
            toks.append('*' if rng.random() < pm else '+')
            toks.append(num(hi))
        return ''.join(toks)
    def terms(length, maxf, digits):
        parts = []
        size = 0
        while size < length - 12:
            f = rng.randint(1, maxf)
            t = '*'.join(str(rng.randint(*digits)) for _ in range(f))
            parts.append(t)
            size += len(t) + 1
        return '+'.join(parts)
    tests = ['7', '0', '2+3*4', '7*0+5*5*2+1', '100*100+9', '1+1', '3*3', '10*10*10', '0*5+0', '1000000000*1000000000',
             '9+9*9+9*9*9', '5*4+3*2+1', '2*3*4*5*6*7*8*9', '1000000000+1000000000*8', '50*0*7+4']
    for n in (2, 3, 4, 5, 6, 8, 10, 12):
        for hi in (9, 9, 99, 1000):
            tests.append(small(n, hi))
    tests.append(small(8, 9, 0.9))
    tests.append(small(8, 9, 0.1))
    # max-size tests (length up to 10^5, results below 2^63)
    t = '+'.join(['1'] * 50000)
    tests.append(t)
    tests.append(terms(100000, 5, (1, 9)))
    tests.append(terms(100000, 3, (0, 9)))
    big = [str(rng.randint(10**8, 10**9)) for _ in range(9000)]
    parts = []
    k = 0
    while sum(len(x) + 1 for x in parts) < 99000 - 30:
        parts.append(str(rng.randint(10**8, 10**9)))
    parts[3] = str(rng.randint(10**8, 10**9)) + '*' + str(rng.randint(10**8, 10**9))
    parts[40] = str(10**9) + '*' + str(10**9)
    parts[77] = str(rng.randint(10**8, 10**9)) + '*' + str(rng.randint(10**8, 10**9))
    tests.append('+'.join(parts))
    tests.append('1' + '*1' * 49999)
    for t in tests:
        assert 0 < len(t) <= 100000 and val(t) < 2**63, len(t)
